  /* ---------- Mondrian frame around everything ---------- */
  .frame {
    border: var(--line) solid var(--black);
    margin: 24px;
    min-height: calc(100vh - 48px);
    display: flex;
    flex-direction: column;
  }

  /* ---------- Top bar ---------- */
  .topbar {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    border-bottom: var(--line) solid var(--black);
  }
  .topbar > div { padding: 14px 22px; }
  .topbar > div + div { border-left: var(--line) solid var(--black); }
  .topbar .kicker {
