    text-transform: uppercase;
    letter-spacing: 0.22em;
    font-size: 0.8rem;
  }
  .topbar .meta { font-size: 0.9rem; font-weight: 700; }
  .cell-red    { background: var(--red); color: var(--white); }
  .cell-yellow { background: var(--yellow); }
  .cell-white  { background: var(--white); }

  /* ---------- Hero ---------- */
  .hero {
    display: grid;
    grid-template-columns: 1.6fr 1fr 1fr;
    grid-template-rows: auto auto auto;
    border-bottom: var(--line) solid var(--black);
  }
  .hero h1 {
    grid-column: 1;
    grid-row: 1 / span 3;
    padding: 48px 40px;
    font-family: 'Archivo Black', 'Archivo', sans-serif;
    font-size: clamp(2.2rem, 6vw, 5rem);
    line-height: 0.98;
    text-transform: uppercase;
    letter-spacing: -0.01em;
    display: flex;
    align-items: center;
  }
  .hero h1 .accent-red { color: var(--red); }
  .hero h1 .accent-blue { color: var(--blue); }
  .hero h1 .accent-yellow {
    color: var(--yellow);
    text-shadow: 2px 2px 0 rgba(23,23,26,0.25);
  }
  .hero-block { padding: 26px 30px; font-size: 1.05rem; }
  .hero-block b { display: block; text-transform: uppercase; letter-spacing: 0.18em; font-size: 0.75rem; margin-bottom: 6px; }
  .hero-block:nth-child(2) { grid-column: 2 / span 2; border-bottom: var(--line) solid var(--black); background: var(--white); }
  .hero-block:nth-child(3) { grid-column: 2; background: var(--blue); color: var(--white); }
  .hero-block:nth-child(4) { grid-column: 3; border-left: var(--line) solid var(--black); background: var(--yellow); }

  /* ---------- Facts strip ---------- */
  .facts {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    border-bottom: var(--line) solid var(--black);
  }
  .fact { padding: 24px 22px; }
  .fact + .fact { border-left: var(--line) solid var(--black); }
  .fact .label {
    text-transform: uppercase;
    letter-spacing: 0.2em;
    font-size: 0.72rem;
    font-weight: 700;
    margin-bottom: 10px;
  }
  .fact .value { font-size: 1.35rem; font-weight: 900; line-height: 1.2; }
  .fact .sub { font-size: 0.85rem; margin-top: 6px; }
  .fact.f-red    { background: var(--red); color: var(--white); }
  .fact.f-blue   { background: var(--blue); color: var(--white); }
  .fact.f-yellow { background: var(--yellow); }
  .fact.f-white  { background: var(--white); }

